const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=['대기방','제시어 제안','익명 투표','질문하기','답변하기','정답 도전','인정 투표','탈출 성공','최종 결과'];
const types=['신사','젊은 신사','귀부인','교수','메이드','탐정','신문 소년','선원','비행사','화가','집사','간호사','기자','마술사','노동자','사교계 여성'];
let players=[{n:'로즈',a:2},{n:localStorage.getItem('wai-name')||'잭',a:Number(localStorage.getItem('wai-avatar')??1)},{n:'올리버',a:3},{n:'엘리스',a:15},{n:'찰리',a:13},{n:'메리',a:4}],page=0,ready=false,choice='',proposal='셜록 홈즈',question='저는 실존 인물인가요?',answer='네, 실제로 존재했던 인물이에요.',guess='홈즈',target=3,remaining=0,timer,logs=[],sound=false;
const portrait=a=>`<div class="portrait" role="img" aria-label="${types[a]}" style="background-position:${a%4*100/3}% ${Math.floor(a/4)*100/3}%"></div>`;
const hero=i=>`<div class="hero">${portrait(players[i].a)}<div class="hero-label">${page?String(i+1).padStart(2,'0')+' ':''}${esc(players[i].n)}</div></div>`;
function tone(){if(!sound)return;let a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);g.gain.value=.03;o.frequency.value=440;o.start();o.stop(a.currentTime+.08);o.onended=()=>a.close()}
function go(p){clearInterval(timer);page=p;choice='';tone();render()}
function clock(n,fn){remaining=n;clearInterval(timer);const tick=()=>{let el=$('#seconds');if(el)el.textContent=remaining+'초'};tick();timer=setInterval(()=>{remaining--;tick();if(remaining<=0){clearInterval(timer);fn()}},1000)}
function render(){let main=page===1||page===2?0:page===4?target:1;$('#phase').textContent=page===0?'대기방 · 6 / 8':titles[page];$('#nav').innerHTML=titles.map((t,i)=>`<button class="${i===page?'active':''}" data-page="${i}">${t}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>go(+b.dataset.page));$('#roster').innerHTML=players.map((p,i)=>`<div class="player ${page&&i===1?'self':''} ${page>=3&&page<=7&&i===1?'current':''}">${portrait(p.a)}<div>${page?String(i+1).padStart(2,'0')+' ':''}${esc(p.n)}<small>${page===0?(i===1?(ready?'준비 완료':'설정 중'):'준비 완료'):page>=3&&i===0?'탈출 1위':page>=7&&i===1?'탈출 2위':main===i?'진행 중':'대기 중'}</small></div></div>`).join('');$('#bottom').innerHTML=page===0?`<div class="characters">${types.map((n,i)=>`<button data-avatar="${i}" class="${players[1].a===i?'selected':''}" aria-label="${n} 선택">${portrait(i)}<small>${n}</small></button>`).join('')}</div>`:players.map((p,i)=>i===main?'':`<div class="card">${portrait(p.a)}<span>${String(i+1).padStart(2,'0')} ${esc(p.n)}</span></div>`).join('');
let body='',eyebrow='A PRIVATE SOCIAL CLUB',time='';
if(page===0)body=`<h1>당신의 자리를<br>준비해 두었습니다.</h1><label for="nick">닉네임</label><input id="nick" maxlength="16" value="${esc(players[1].n)}"><div class="paper">선택한 캐릭터 · ${types[players[1].a]}<br><small>캐릭터는 다른 플레이어와 중복 선택할 수 있습니다.</small></div><div class="actions"><button id="ready">${ready?'준비 취소':'준비 완료'}</button><button id="start" ${ready?'':'disabled'}>체험 시작</button></div><p class="muted">실제 게임은 전원 준비 후 방장이 시작합니다.<br>아래에서 16종의 프로필을 선택하세요.</p>`;
if(page===1){time='15';body=`<h1>로즈의 비밀 인물을<br>제안하세요.</h1><input id="proposal" maxlength="40" placeholder="인물 이름을 입력하세요"><div class="actions"><button id="submit">제안 제출</button></div><p class="muted">대상 플레이어에게는 후보가 보이지 않습니다.<br>다른 참가자들의 제안은 체험용으로 준비되어 있습니다.</p>`}
if(page===2){time='15';body=`<h1>어떤 인물이 어울릴까요?</h1><div class="choices">${[...new Set([proposal,'찰리 채플린','이순신','해리 포터'])].map(n=>`<button data-choice="${esc(n)}">${esc(n)}</button>`).join('')}</div><div class="actions"><button id="vote" disabled>투표 확정</button></div><p class="muted">본인 제안에도 투표 가능 · 투표는 익명<br>동점이면 공동 1위 후보 중 무작위 선정합니다.</p>`}
if(page===3){time='10';body=`<span class="eyebrow">ROUND 02 · 질문 차례</span><h1>누구에게 물어볼까요?</h1><input id="question" value="${esc(question)}" maxlength="100" aria-label="질문"><div class="choices" style="margin-top:15px">${players.map((p,i)=>i===1?'':`<button data-target="${i}">${esc(p.n)}</button>`).join('')}</div><div class="actions"><button id="ask" disabled>질문 제출</button><button id="guess">정답 도전</button></div><p class="muted">체험은 2바퀴째입니다. 실제 게임의 첫 바퀴에는 정답 도전이 잠깁니다.</p>`}
if(page===4){time='20';body=`<span class="eyebrow">${esc(players[1].n)}의 질문</span><h1>${esc(question)}</h1><input id="answer" maxlength="150" placeholder="답변을 입력하세요" value="${esc(answer)}"><div class="actions"><button id="respond">답변 공개</button></div><p class="muted">답변자 조작 체험 · 답변 제출 후 5초간 공개합니다.<br>아래 채팅을 보내면 주변에 떠올랐다가 사라집니다.</p>`}
if(page===5){time='10';body=`<span class="eyebrow">ROUND 02 · 정답 도전</span><h1>나는 누구일까요?</h1><input id="guessInput" maxlength="40" placeholder="정답 입력"><div class="actions"><button id="sendGuess">정답 제출</button></div><p class="muted">제시어와 일치하면 자동 정답.<br>불일치하면 나머지 플레이어가 인정 여부를 선택합니다.</p>`}
if(page===6){time='10';body=`<span class="eyebrow">투표 참여자 시점 · 도전자에게 비공개</span><h1>정답으로 인정할까요?</h1><div class="paper">지정된 정답: <b>셜록 홈즈</b><br>제출한 답: <b>${esc(guess)}</b></div><div class="actions"><button id="accept">인정</button><button class="danger" id="reject">인정하지 않음</button></div><p class="muted">예시: 다른 4명 중 2명 인정 · 2명 불인정<br>당신의 선택까지 합쳐 5명 중 3명 이상이면 정답.<br>도전자는 이 화면 대신 결과 대기 화면을 보게 됩니다.</p>`}
if(page===7)body=`<span class="eyebrow">CONGRATULATIONS</span><div class="rank">탈출 2위</div><h1>${esc(players[1].n)} 님, 정답입니다!</h1><div class="paper">당신의 정체는 <b>셜록 홈즈</b>였습니다.</div><p class="muted">질문 차례는 종료되지만 답변자로 계속 참여할 수 있습니다.</p><div class="actions"><button id="observe">관전 체험</button><button id="results">결과 화면</button></div>`;
$('#stage').innerHTML=page===8?`<div class="results"><span class="eyebrow">THE EVENING'S RESULTS</span><h1>오늘의 탈출 기록</h1><table><thead><tr><th>등수</th><th>플레이어</th><th>정체</th><th>결과</th></tr></thead><tbody>${[0,1,3,2,5,4].map((i,k)=>`<tr><td>${k+1}위</td><td>${String(i+1).padStart(2,'0')} ${esc(players[i].n)}</td><td>${['마리 퀴리','셜록 홈즈','찰리 채플린','이순신','해리 포터','아인슈타인'][k]}</td><td>${k===5?'미탈출':'정답'}</td></tr>`).join('')}</tbody></table><div class="actions"><button id="return">대기방으로</button></div><p class="muted">결과 화면 구성 확인용 예시 순위입니다.</p></div>`:`${hero(main)}<div class="panel"><span class="eyebrow">${eyebrow}</span>${time?'<span class="timer" id="seconds">'+time+'초</span>':''}${body}</div>`;
const on=(id,f)=>{if($(id))$(id).onclick=f};
if(page===0){$('#nick').onchange=e=>{players[1].n=e.target.value.trim()||'잭';localStorage.setItem('wai-name',players[1].n);render()};$('#bottom').querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{players[1].a=+b.dataset.avatar;localStorage.setItem('wai-avatar',players[1].a);render()});on('#ready',()=>{ready=!ready;render()});on('#start',()=>go(1))}
if(page===1){const submit=()=>{proposal=$('#proposal').value.trim()||'셜록 홈즈';go(2)};on('#submit',()=>{if(!$('#proposal').value.trim())return $('#proposal').focus();submit()});clock(15,submit)}
if(page===2){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choice=b.dataset.choice;document.querySelectorAll('[data-choice]').forEach(c=>c.classList.toggle('selected',c===b));$('#vote').disabled=false});on('#vote',()=>{logs.push('로즈 후보 투표: '+choice+' (체험)');go(3)});clock(15,()=>go(3))}
if(page===3){document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{target=+b.dataset.target;document.querySelectorAll('[data-target]').forEach(c=>c.classList.toggle('selected',c===b));$('#ask').disabled=false});on('#ask',()=>{question=$('#question').value.trim();if(!question)return $('#question').focus();go(4)});on('#guess',()=>go(5));clock(10,()=>{logs.push('질문 입력 시간 초과 · 차례 패스');go(5)})}
if(page===4){const reveal=()=>{clearInterval(timer);answer=$('#answer').value.trim()||'시간 내 답변하지 않았습니다';logs.push(question+' → '+answer);$('.panel').innerHTML=`<h1>${esc(question)}</h1><div class="paper">${esc(answer)}</div><span id="seconds"></span><p class="muted">답변 공개 후 다음 화면으로 이동합니다.</p>`;clock(5,()=>go(5))};on('#respond',reveal);clock(20,()=>{$('#answer').value='';reveal()})}
if(page===5){on('#sendGuess',()=>{guess=$('#guessInput').value.trim();if(!guess)return $('#guessInput').focus();go(guess==='셜록 홈즈'?7:6)});clock(10,()=>{logs.push('정답 입력 시간 초과 · 차례 패스');go(3)})}
if(page===6){on('#accept',()=>go(7));on('#reject',()=>{logs.push('정답 인정 2 / 5 · 오답');go(3)});clock(10,()=>{logs.push('인정 투표 시간 초과 · 기권, 오답');go(3)})}
on('#observe',()=>go(4));on('#results',()=>go(8));on('#return',()=>{ready=false;go(0)})}
$('#chat').onsubmit=e=>{e.preventDefault();let s=$('#message').value.trim();if(!s)return;let d=document.createElement('div');d.className='bubble';d.textContent=players[1].n+': '+s;$('#stage').append(d);setTimeout(()=>d.remove(),5000);$('#message').value=''};$('#history').onclick=()=>{$('#log').innerHTML=logs.length?logs.map(l=>'<p>'+esc(l)+'</p>').join(''):'아직 기록이 없습니다.';$('#records').showModal()};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'소리 켜짐':'소리 꺼짐';tone()};go(0);
